class Solution {
    public List<Integer> peopleIndexes(List<List<String>> favoriteCompanies){
        List<Set<String>> sets=new ArrayList<>();
        for(List<String> companies:favoriteCompanies)sets.add(new HashSet<>(companies));
        List<Integer> answer=new ArrayList<>();
        for(int i=0;i<sets.size();i++){
            boolean subset=false;
            for(int j=0;j<sets.size()&&!subset;j++)if(i!=j&&sets.get(j).size()>=sets.get(i).size()&&sets.get(j).containsAll(sets.get(i)))subset=true;
            if(!subset)answer.add(i);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun peopleIndexes(favoriteCompanies:List<List<String>>):List<Int>{
        val sets=favoriteCompanies.map{
            it.toSet()
        };
        return sets.indices.filter{
            i->sets.indices.none{
                j->i!=j&&sets[j].size>=sets[i].size&&sets[j].containsAll(sets[i])
            }
        }
    }
}

code.cpp:
class Solution {
    public: vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies){
        vector<unordered_set<string>> sets;
        for(auto& companies:favoriteCompanies)sets.emplace_back(companies.begin(),companies.end());
        vector<int> answer;
        for(int i=0;i<(int)sets.size();++i){
            bool subset=false;
            for(int j=0;j<(int)sets.size()&&!subset;++j)if(i!=j&&sets[j].size()>=sets[i].size()){
                subset=true;
                for(auto& company:sets[i])if(!sets[j].count(company)){
                    subset=false;
                    break;
                }
            }
            if(!subset)answer.push_back(i);
        }
        return answer;
    }
};
